import { and, count, desc, eq, gte, inArray, lt, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { activityEvents, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toActivityEvent } from "./_mappers";
import type { ActivityFilterInput } from "@/schemas/activity";
import type { ActivityEvent, ActivitySubjectKind } from "@/types/activity";
import type { IsoTimestamp, OrgId, Page } from "@/types/common";

export async function insertActivity(
  event: Omit<ActivityEvent, "id">,
): Promise<ActivityEvent> {
  const row = getDb()
    .insert(activityEvents)
    .values({
      id: newId(),
      orgId: event.orgId,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      projectId: event.projectId,
      summary: event.summary,
      metadata: JSON.stringify(event.metadata),
      occurredAt: event.occurredAt,
    })
    .returning()
    .get();

  return toActivityEvent(row);
}

export async function listActivity(
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  const db = getDb();
  const sort = {
    sortColumn: activityEvents.occurredAt,
    idColumn: activityEvents.id,
  };

  const filters = compact(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.action === undefined || input.action.length === 0
      ? undefined
      : inArray(activityEvents.action, [...input.action]),
    input.actorId === undefined
      ? undefined
      : eq(activityEvents.actorId, input.actorId),
    input.projectId === undefined
      ? undefined
      : eq(activityEvents.projectId, input.projectId),
    input.subjectKind === undefined
      ? undefined
      : eq(activityEvents.subjectKind, input.subjectKind),
    input.since === undefined
      ? undefined
      : gte(activityEvents.occurredAt, input.since),
    input.until === undefined
      ? undefined
      : lte(activityEvents.occurredAt, input.until),
  );

  const total = db
    .select({ value: count() })
    .from(activityEvents)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(activityEvents)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    toActivityEvent,
    (row) => ({ id: row.id, sortValue: row.occurredAt }),
  );
}

/** The "history" tab of one issue, project or member. */
export async function listActivityForSubject(
  orgId: OrgId,
  subjectKind: ActivitySubjectKind,
  subjectId: string,
): Promise<readonly ActivityEvent[]> {
  const rows = getDb()
    .select()
    .from(activityEvents)
    .where(
      and(
        orgPredicate(activityEvents.orgId, orgId),
        eq(activityEvents.subjectKind, subjectKind),
        eq(activityEvents.subjectId, subjectId),
      ),
    )
    .orderBy(desc(activityEvents.occurredAt))
    .all();

  return rows.map(toActivityEvent);
}

/**
 * The only sanctioned deletion path: the retention sweep. `before` comes from
 * the plan's `retentionDays`, never from a user-supplied date.
 */
export async function purgeActivityBefore(
  orgId: OrgId,
  before: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(activityEvents)
    .where(
      and(
        orgPredicate(activityEvents.orgId, orgId),
        lt(activityEvents.occurredAt, before),
      ),
    )
    .returning({ id: activityEvents.id })
    .all();

  return rows.length;
}
/**
 * Turns a repository `Page` into what the pagination UI needs. Repositories
 * return cursor pages; the UI wants page counts and a "there is more" cursor,
 * and this module is the translation between the two.
 */
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from "@/config/constants";
import type { Page } from "@/types/common";
import { makePage } from "@/types/common";

/** Number of pages a total spans; always at least 1 so the UI can render "1 of 1". */
export function pageCount(total: number, perPage: number): number {
  const size = clampPageSize(perPage);
  if (total <= 0) return 1;
  return Math.ceil(total / size);
}

/** Clamps a caller-supplied page size into the range the schemas allow. */
export function clampPageSize(perPage: number): number {
  if (!Number.isFinite(perPage) || perPage <= 0) return DEFAULT_PAGE_SIZE;
  return Math.min(Math.floor(perPage), MAX_PAGE_SIZE);
}

export function emptyPage<T>(): Page<T> {
  return makePage<T>([], null, 0);
}

/**
 * Trims an over-fetched row set to one page. Repositories query `limit + 1`
 * rows; if the extra row came back there is a next page, and its cursor is
 * the last kept row's cursor.
 */
export function sliceToPage<T>(
  items: readonly T[],
  limit: number,
  total: number,
  cursorOf: (item: T) => string,
): Page<T> {
  const size = clampPageSize(limit);
  const hasMore = items.length > size;
  const kept = hasMore ? items.slice(0, size) : items.slice();
  const last = kept[kept.length - 1];
  return makePage(kept, hasMore && last !== undefined ? cursorOf(last) : null, total);
}
import { z } from "zod";

/**
 * Coercions for reading pagination out of `searchParams`. Remember that in
 * Next 16 `searchParams` is a Promise — `await` it before parsing.
 */
export const searchParamsPaginationSchema = z.object({
  page: z.coerce.number().int().min(1).catch(1),
  perPage: z.coerce.number().int().min(1).max(100).catch(25),
  cursor: z.string().optional(),
});

export const searchParamsSortSchema = z.object({
  sort: z.string().max(40).optional(),
  dir: z.enum(["asc", "desc"]).catch("desc"),
});

export function toOffset(page: number, perPage: number): number {
  return (page - 1) * perPage;
}

export type SearchParamsPagination = z.infer<
  typeof searchParamsPaginationSchema
>;
export type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;

